-- Extend v2 Vietnamese payload; old payloads without aliases and v1 records remain valid.
ALTER TABLE question DROP CHECK ck_question_values,
 ADD CONSTRAINT ck_question_values CHECK (schema_version IN (1,2) AND (schema_version=2 OR mode='QUIZ') AND order_index>0 AND CHAR_LENGTH(TRIM(content))>0 AND created_at_ms>=0 AND (deleted_at_ms IS NULL OR deleted_at_ms>=created_at_ms) AND ((mode='QUIZ' AND payload IS NULL AND correct_option IS NOT NULL AND correct_option IN ('A','B','C','D') AND option_a IS NOT NULL AND CHAR_LENGTH(TRIM(option_a))>0 AND option_b IS NOT NULL AND CHAR_LENGTH(TRIM(option_b))>0 AND option_c IS NOT NULL AND CHAR_LENGTH(TRIM(option_c))>0 AND option_d IS NOT NULL AND CHAR_LENGTH(TRIM(option_d))>0) OR (schema_version=2 AND option_a IS NULL AND option_b IS NULL AND option_c IS NULL AND option_d IS NULL AND correct_option IS NULL AND payload IS NOT NULL AND ((mode='RIDDLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}}}', payload)) OR (mode='SONG' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='IMAGE_WORD' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='CLUES' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","hints"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"hints":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["offsetMs","text"],"properties":{"offsetMs":{"type":"integer","minimum":0},"text":{"type":"string","minLength":1,"maxLength":2000}}}}}}', payload)) OR (mode='VIETNAMESE_PUZZLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["pieces","correctOrder"],"properties":{"pieces":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}},"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300}},"matchingPolicy":{"type":"string","enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}},"dependencies":{"acceptedAnswers":["matchingPolicy"],"matchingPolicy":["acceptedAnswers"]}}', payload)) OR (mode='ORDERING' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["items","correctOrder"],"properties":{"items":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload))))));

ALTER TABLE game_question DROP CHECK ck_game_question_values,
 ADD CONSTRAINT ck_game_question_values CHECK (schema_version IN (1,2) AND order_index BETWEEN 1 AND 50 AND question_duration_ms>0 AND phase IN ('DECISION','QUESTION_OPEN','QUESTION_CLOSED','SCORING','RESULT') AND CHAR_LENGTH(TRIM(content))>0 AND (opened_at_ms IS NULL OR opened_at_ms>=0) AND (deadline_at_ms IS NULL OR (opened_at_ms IS NOT NULL AND deadline_at_ms>opened_at_ms)) AND (scored_at_ms IS NULL OR (opened_at_ms IS NOT NULL AND scored_at_ms>=opened_at_ms)) AND ((schema_version=1 AND mode='QUIZ' AND stage_id IS NULL AND stage_question_index IS NULL) OR (schema_version=2 AND stage_id IS NOT NULL AND stage_question_index IS NOT NULL AND stage_question_index BETWEEN 1 AND 50)) AND ((mode='QUIZ' AND payload IS NULL AND correct_option IS NOT NULL AND correct_option IN ('A','B','C','D') AND option_a IS NOT NULL AND CHAR_LENGTH(TRIM(option_a))>0 AND option_b IS NOT NULL AND CHAR_LENGTH(TRIM(option_b))>0 AND option_c IS NOT NULL AND CHAR_LENGTH(TRIM(option_c))>0 AND option_d IS NOT NULL AND CHAR_LENGTH(TRIM(option_d))>0) OR (schema_version=2 AND option_a IS NULL AND option_b IS NULL AND option_c IS NULL AND option_d IS NULL AND correct_option IS NULL AND payload IS NOT NULL AND ((mode='RIDDLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}}}', payload)) OR (mode='SONG' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='IMAGE_WORD' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='CLUES' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","hints"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"hints":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["offsetMs","text"],"properties":{"offsetMs":{"type":"integer","minimum":0},"text":{"type":"string","minLength":1,"maxLength":2000}}}}}}', payload)) OR (mode='VIETNAMESE_PUZZLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["pieces","correctOrder"],"properties":{"pieces":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}},"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300}},"matchingPolicy":{"type":"string","enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}},"dependencies":{"acceptedAnswers":["matchingPolicy"],"matchingPolicy":["acceptedAnswers"]}}', payload)) OR (mode='ORDERING' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["items","correctOrder"],"properties":{"items":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload))))));
